    lemma_clear_out_preserves_retained_provenance(scheduled);
    reveal(crate::handler::spec_on_event);
    reveal(crate::handler::spec_on_known_event);
    reveal(crate::handler::spec_schedule_wake);
    reveal(crate::state::spec_emit);
